import { useEffect, useState } from "react";
import EmployeeService from "../Services/EmployeeService";
import { useNavigate } from "react-router-dom";

const ListEmployee = () => {
    const navigate = useNavigate();
    const [employees, setEmployees] = useState([]);

    const editEmployee = (id) => navigate(`add-employee/${id}`);
    const deleteEmployee = (id) => {
        EmployeeService.DeleteEmployee(id).then(() => {
            setEmployees(employees.filter(emp => emp.id !== id));
        });
    };
    const viewEmployee = (id) => navigate(`view-employee/${id}`);

    useEffect(() => {
        EmployeeService.getEmployees().then((res) => setEmployees(res.data)).catch(err => console.log(err));
    }, []);

    return (
        <div style={{ padding: '28px' }}>

            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '24px' }}>
                <h4 style={{ fontWeight: '700', color: '#343a40', margin: 0 }}>
                    <i className="fa fa-users me-2"></i>Employees
                </h4>
                <span style={{ background: '#6c757d', color: '#fff', borderRadius: '20px', padding: '4px 16px', fontSize: '13px' }}>
                    Total: {employees.length}
                </span>
            </div>

            <div style={{ background: '#fff', borderRadius: '8px', boxShadow: '0 2px 12px rgba(0,0,0,0.08)', overflow: 'hidden' }}>
                <table className="table table-hover mb-0">
                    <thead style={{ background: '#414447', color: '#fff' }}>
                        <tr>
                            <th style={{ padding: '14px 20px', fontWeight: '600', fontSize: '13px', border: 'none' }}>#</th>
                            <th style={{ padding: '14px 20px', fontWeight: '600', fontSize: '13px', border: 'none' }}>First Name</th>
                            <th style={{ padding: '14px 20px', fontWeight: '600', fontSize: '13px', border: 'none' }}>Last Name</th>
                            <th style={{ padding: '14px 20px', fontWeight: '600', fontSize: '13px', border: 'none' }}>Email</th>
                            <th style={{ padding: '14px 20px', fontWeight: '600', fontSize: '13px', border: 'none', textAlign: 'center' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {employees.map((employee, index) => (
                            <tr key={employee.id} style={{ fontSize: '14px', color: '#495057' }}>
                                <td style={{ padding: '13px 20px', verticalAlign: 'middle', color: '#adb5bd' }}>{index + 1}</td>
                                <td style={{ padding: '13px 20px', verticalAlign: 'middle' }}>{employee.firstName}</td>
                                <td style={{ padding: '13px 20px', verticalAlign: 'middle' }}>{employee.lastName}</td>
                                <td style={{ padding: '13px 20px', verticalAlign: 'middle' }}>{employee.email}</td>
                                <td style={{ padding: '13px 20px', verticalAlign: 'middle', textAlign: 'center' }}>
                                    <i className="fa fa-eye" onClick={() => viewEmployee(employee.id)}
                                        title="View" style={{ cursor: 'pointer', color: '#6c757d', fontSize: '16px', marginRight: '14px' }}></i>
                                    <i className="fa fa-pencil" onClick={() => editEmployee(employee.id)}
                                        title="Edit" style={{ cursor: 'pointer', color: '#414447', fontSize: '16px', marginRight: '14px' }}></i>
                                    <i className="fa fa-trash" onClick={() => deleteEmployee(employee.id)}
                                        title="Delete" style={{ cursor: 'pointer', color: '#dc3545', fontSize: '16px' }}></i>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default ListEmployee;
